<?php
declare(strict_types=1); require __DIR__.'/includes/bootstrap.php';
if(current_user()){header('Location: dashboard.php');exit;}
$error='';
try { $count=(int)db()->query('SELECT COUNT(*) FROM dbo.users')->fetchColumn(); if($count===0){header('Location: setup.php');exit;} }
catch(Throwable $e){$error='Database is not ready. Open setup.php first. Details: '.$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST' && !$error){verify_csrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$stmt=db()->prepare('SELECT TOP (1) id,username,password_hash,full_name,role,is_active FROM dbo.users WHERE username=?');$stmt->execute([$username]);$u=$stmt->fetch();if($u && (int)$u['is_active']===1 && password_verify($password,$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'username'=>$u['username'],'full_name'=>$u['full_name'],'role'=>$u['role']];audit_log('LOGIN','user',(int)$u['id'],'Successful login');header('Location: ModelData.php?process=cut');exit;}else{$error='Invalid username or password, or the account is inactive.';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login · Production Data Explorer</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/csv.css"><link rel="stylesheet" href="assets/admin.css"></head><body class="auth-body"><main class="auth-card"><div class="auth-logo">P</div><div class="eyebrow">PRODUCTION DATA EXPLORER</div><h1>Sign in</h1><p>Sign in to manage process CSV sources and view the change history.</p><?php if($error):?><div class="notice notice-error"><strong>Unable to sign in</strong><span><?=h($error)?></span></div><?php endif;?><form method="post" class="auth-form"><?=csrf_field()?><label class="field"><span>Username</span><input name="username" autocomplete="username" required autofocus></label><label class="field"><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label><button class="btn btn-primary" type="submit">Sign in</button></form><p class="auth-foot">First-time setup? <a href="setup.php">Create the administrator account</a></p></main></body></html>